                VerifyOrReturn(CheckDecodeValue(chip::app::DataModel::Decode(*data, value)));
                VerifyOrReturn(CheckConstraintType("value", "list", "list"));
                VerifyOrReturn(CheckConstraintContains("value", value, 0UL));
